#!/usr/bin/env bash
#
# eval-plan-quality.sh <playbook-dir>
#
# Deterministic structural eval of a playbook generated by `converge plan`.
# Walks every TASK.md under <playbook-dir>, classifies it (executable /
# container / wbs) by frontmatter, and grep-checks the conservative field
# set + body subsections the *planner* is now expected to emit.
#
# This is a target rubric for new planner output, NOT a regression
# baseline. Hand-written playbooks under examples/ pre-date these
# conventions and may legitimately fail (no `## Per-spawn child shape`
# in older WBS tasks, schemas linked from a sibling schemas/ dir
# instead of inlined, etc.). The point of the eval is to confirm the
# planner is producing the right shape going forward.
#
# Exit 0 = pass. Exit 1 = at least one TASK.md failed; per-failure list
# printed to stderr.
#
# Usage:
#   scripts/eval-plan-quality.sh .converge/playbooks/default

set -u

dir="${1:-}"
if [[ -z "$dir" || ! -d "$dir" ]]; then
  echo "usage: $0 <playbook-dir>" >&2
  exit 2
fi

fail=0
total=0

# Frontmatter helpers — extract the YAML block between the first two `---`.
extract_frontmatter() {
  awk '/^---[[:space:]]*$/{c++; if(c==2) exit; next} c==1{print}' "$1"
}

has_key() {
  # has_key <file> <key>  — true if frontmatter has a top-level `<key>:` line.
  # Accept both `key: value` (scalar) and `key:` (block list/map start).
  extract_frontmatter "$1" | grep -qE "^${2}:([[:space:]]|$)"
}

forbids_key() {
  # forbids_key <file> <key>  — true if frontmatter does NOT have `<key>:`.
  ! has_key "$1" "$2"
}

classify() {
  # echo "executable" | "container" | "wbs" | "unknown" by frontmatter.
  local fm
  fm=$(extract_frontmatter "$1")
  if grep -qE "^wbs:([[:space:]]|$)" <<<"$fm"; then
    # Reject `wbs: false` etc; we want a structured wbs block.
    if grep -qE "^[[:space:]]+(type|path):" <<<"$fm"; then
      echo wbs; return
    fi
  fi
  if grep -qE "^outputs:([[:space:]]|$)" <<<"$fm" || grep -qE "^checks:([[:space:]]|$)" <<<"$fm"; then
    echo executable; return
  fi
  echo container
}

report() {
  # report <file> <message>
  echo "FAIL  $1: $2" >&2
  fail=$((fail+1))
}

while IFS= read -r -d '' f; do
  total=$((total+1))
  # Skip the playbook root TASK.md (if any) and PLAN.md proposed siblings.
  case "$f" in
    *.proposed) continue ;;
  esac

  kind=$(classify "$f")

  # Common required fields across all kinds.
  for key in id title description tags; do
    has_key "$f" "$key" || report "$f" "missing frontmatter \`$key:\`"
  done

  case "$kind" in
    executable)
      for key in outputs checks; do
        has_key "$f" "$key" || report "$f" "executable missing \`$key:\`"
      done
      forbids_key "$f" "wbs" || report "$f" "executable must not have \`wbs:\`"

      # If outputs lists a manifest (.json / .yaml / .toml), body must
      # carry both the schema and an example.
      if extract_frontmatter "$f" | grep -qE "\.(json|yaml|yml|toml)([[:space:]]|$)"; then
        grep -qE "^## Output schema" "$f" || \
          report "$f" "manifest producer missing \`## Output schema\` block"
        grep -qE "^## Example" "$f" || \
          report "$f" "manifest producer missing \`## Example\` block"
      fi
      ;;

    container)
      forbids_key "$f" "outputs" || report "$f" "container must not have \`outputs:\`"
      forbids_key "$f" "checks"  || report "$f" "container must not have \`checks:\`"
      forbids_key "$f" "wbs"     || report "$f" "container must not have \`wbs:\`"

      grep -qE "^### Inherited context" "$f" || \
        report "$f" "container missing \`### Inherited context\` subsection"

      # Cap inherited-context bullets at 5.
      bullets=$(awk '
        /^### Inherited context/ {inb=1; next}
        inb && /^#/ {exit}
        inb && /^[[:space:]]*-[[:space:]]/ {n++}
        END {print n+0}
      ' "$f")
      if [[ "$bullets" -gt 5 ]]; then
        report "$f" "\`### Inherited context\` has $bullets bullets (max 5)"
      fi
      ;;

    wbs)
      forbids_key "$f" "outputs" || report "$f" "wbs must not have \`outputs:\`"
      forbids_key "$f" "checks"  || report "$f" "wbs must not have \`checks:\`"

      grep -qE "^## Per-spawn child shape" "$f" || \
        report "$f" "wbs missing \`## Per-spawn child shape\` section"

      # wbs/index.js must exist alongside.
      wbs_dir=$(dirname "$f")
      if [[ ! -f "$wbs_dir/wbs/index.js" ]]; then
        report "$f" "wbs missing \`wbs/index.js\` companion script"
      fi
      ;;
  esac
done < <(find "$dir" -name TASK.md -print0)

echo
echo "Scanned: $total TASK.md files"
if [[ "$fail" -gt 0 ]]; then
  echo "Failures: $fail"
  exit 1
fi
echo "All checks passed."
exit 0
